// Sign-in code email (spec/sync.md "信箱驗證碼"): fixed subject, plain text and HTML bodies.

export interface RenderedMail {
  subject: string;
  text: string;
  html: string;
}

export function renderCodeEmail(code: string): RenderedMail {
  const text = [`你的 DayDo 驗證碼：${code}`, '', '驗證碼 10 分鐘內有效，只能使用一次。', '如果不是你本人要求登入，請忽略這封信。'].join('\n');
  // The code is generated by the server (digits only), so it needs no HTML escaping.
  const html = `<!doctype html>
<html lang="zh-Hant"><head><meta charset="utf-8"><title>你的 DayDo 驗證碼</title></head>
<body style="font-family:-apple-system,BlinkMacSystemFont,'Helvetica Neue',sans-serif;color:#1f2328">
<p>你的 DayDo 驗證碼：</p>
<p style="font-size:28px;font-weight:600;letter-spacing:6px">${code}</p>
<p>驗證碼 10 分鐘內有效，只能使用一次。</p>
<p style="color:#6e7781">如果不是你本人要求登入，請忽略這封信。</p>
</body></html>`;
  return { subject: '你的 DayDo 驗證碼', text, html };
}
